/**
 *
 * @export
 * @interface TimeSeriesItem
 */
export interface TimeSeriesItem {
    /**
     * Datetime at local exchange time referring to when the bar with specified interval was opened.
     * @type {string}
     * @memberof TimeSeriesItem
     */
    datetime: string;
    /**
     * Price at the opening of current bar
     * @type {string}
     * @memberof TimeSeriesItem
     */
    open: string;
    /**
     * Highest price which occurred during the current bar.
     * @type {string}
     * @memberof TimeSeriesItem
     */
    high: string;
    /**
     * Lowest price which occurred during the current bar.
     * @type {string}
     * @memberof TimeSeriesItem
     */
    low: string;
    /**
     * Close price at the end of the bar.
     * @type {string}
     * @memberof TimeSeriesItem
     */
    close: string;
    /**
     * Trading volume which occurred during the current bar
     * @type {string}
     * @memberof TimeSeriesItem
     */
    volume?: string;
}
/**
 * Check if a given object implements the TimeSeriesItem interface.
 */
export declare function instanceOfTimeSeriesItem(value: object): value is TimeSeriesItem;
export declare function TimeSeriesItemFromJSON(json: any): TimeSeriesItem;
export declare function TimeSeriesItemFromJSONTyped(json: any, ignoreDiscriminator: boolean): TimeSeriesItem;
export declare function TimeSeriesItemToJSON(json: any): TimeSeriesItem;
export declare function TimeSeriesItemToJSONTyped(value?: TimeSeriesItem | null, ignoreDiscriminator?: boolean): any;
